import DataLoader from 'dataloader';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { Book } from './book.entity';

@Injectable()
export class AuthorBooksLoaderFactory {
  constructor(
    @InjectRepository(Book)
    private readonly bookRepo: Repository<Book>,
  ) {}

  // Contract callers rely on: the loader matches results back to callers by
  // POSITION in `authorIds`, so the batch fn must return exactly one array
  // per key, in the same order as `authorIds`.
  createLoader(): DataLoader<string, Book[]> {
    return new DataLoader<string, Book[]>((authorIds) =>
      this.batchLoadBooks(authorIds),
    );
  }

  private async batchLoadBooks(
    authorIds: readonly string[],
  ): Promise<Book[][]> {
    // One batched query against the data source instead of N separate ones.
    const rows = await this.bookRepo.find({
      where: { authorId: In([...authorIds]) },
    });

    // Group rows into per-author buckets, keyed by first-seen order in `rows`.
    const grouped: Record<string, Book[]> = {};
    for (const row of rows) {
      if (!grouped[row.authorId]) {
        grouped[row.authorId] = [];
      }
      grouped[row.authorId].push(row);
    }

    // Return the grouped lists in the order they were built above.
    return Object.values(grouped);
  }
}
